  var mc = new PIXI.MovieClip(textures);
  mc.loop = true;
  mc.scale.x = mc.scale.y = 2;

  container.addChild(mc);
  movieClips.push(mc);

  pixiAnimationSpeedHandler.addClip(mc, 24);
  pixiAnimationSpeedHandler.start();
  mc.play();

  animate();
